10.11
{{- range .UsageDescriptions}}
{{.Key}}
{{.Value}}
{{- end}}
{{- if .FileAssociations}}
CFBundleDocumentTypes

	{{- range .FileAssociations}}

		CFBundleTypeName
		{{.Name}}
		CFBundleTypeRole
		{{.Role}}
		{{- if .Extensions}}
		CFBundleTypeExtensions

			{{- range .Extensions}}
			{{.}}
			{{- end}}

		{{- end}}
		{{- if .MimeTypes}}
		CFBundleTypeMIMETypes

			{{- range .MimeTypes}}
			{{.}}
			{{- end}}

		{{- end}}
		{{- if .Icon}}
		CFBundleTypeIconFile
		{{.Icon}}
		{{- end}}

	{{- end}}

{{- end}}
{{- if .URLSchemes}}
CFBundleURLTypes


		CFBundleURLName
		{{.AppID}}
		CFBundleURLSchemes

			{{- range .URLSchemes}}
			{{.}}
			{{- end}}



{{- end}}
